// Prep documents generated by BRAIN (high thinking): brief.md, qa_bank.md (+ qa.json), gaps.md and
// per-slide talking points. Every claim has to cite a SOURCE tag from the digest; citations are
// checked afterwards and anything ungrounded is marked ⚠️ UNVERIFIED.
import type { CueConfig } from '../main/config'
import { generateJson, streamBrain } from '../main/gemini/brain'
import type { Gemini } from '../main/gemini/client'
import type { SlideInfo, SlidePrep } from '../main/knowledge'
import { Bm25, cleanSource, estimateTokens, type Chunk, type QaEntry } from '../main/retrieval'
import type { Manifest } from './ingest'

const skipLog = (m: string) => console.log(`  ↪ ${m}; trying the next model`)

const KIND_ORDER = ['deck', 'doc', 'notebook', 'chat', 'data', 'code'] as const
const KIND_SHARE: Record<string, number> = { deck: 0.15, doc: 0.3, notebook: 0.1, chat: 0.25, data: 0.03, code: 0.3 }

/**
 * Picks the chunks prep sends to Gemini within `budget` tokens: each kind gets a share, filled in
 * order of relevance to the meeting topic + keywords; unused share is redistributed.
 */
export function selectDigest(chunks: Chunk[], cfg: CueConfig, budget: number): Chunk[] {
  const query = `${cfg.meeting.topic} ${cfg.keywords.join(' ')} readme overview design decision result validation next steps`
  const bm = new Bm25(chunks, (c) => `${c.source} ${c.text}`)
  const score = new Map(bm.search(query, chunks.length).map((h) => [h.item.id, h.score]))
  const isReadme = (c: Chunk) => /readme|overview|notes?|summary|progress/i.test(c.source)
  const ranked = (kind: string) =>
    chunks
      .filter((c) => c.kind === kind)
      .sort((a, b) => (isReadme(b) ? 5 : 0) + (score.get(b.id) ?? 0) - ((isReadme(a) ? 5 : 0) + (score.get(a.id) ?? 0)))
  const picked = new Set<string>()
  let used = 0
  const take = (list: Chunk[], cap: number) => {
    let spent = 0
    for (const c of list) {
      if (picked.has(c.id) || spent + c.tokens > cap || used + c.tokens > budget) continue
      picked.add(c.id)
      spent += c.tokens
      used += c.tokens
    }
  }
  for (const k of KIND_ORDER) take(ranked(k), budget * (KIND_SHARE[k] ?? 0.1))
  for (const k of KIND_ORDER) take(ranked(k), budget) // leftovers
  // Present in a stable, readable order: by kind, then file, then position.
  return chunks.filter((c) => picked.has(c.id))
}

export function digestText(chunks: Chunk[]): string {
  return chunks.map((c) => `### SOURCE: ${c.source}${c.date ? ` (${c.date.slice(0, 10)})` : ''}\n${c.text}`).join('\n\n')
}

function manifestSummary(m: Manifest): string {
  const raw = m.rawData
    .slice(0, 15)
    .map((g) => `- ${g.folder}: ${g.count} files (${Object.keys(g.exts).join(', ')})`)
    .join('\n')
  const chats = m.chats.filter((c) => c.kept)
  return `Sources indexed: ${m.totals.files} files, ${m.totals.chunks} chunks, ≈${m.totals.tokens.toLocaleString()} tokens.
Chat sessions kept: ${chats.length} of ${m.chats.length}${chats.length ? ` (${chats[0].started?.slice(0, 10) ?? '?'} … ${chats[chats.length - 1].started?.slice(0, 10) ?? '?'})` : ''}.
Raw data folders (names/sizes only):\n${raw || '- none found'}`
}

const GROUNDING = (me: string) => `GROUNDING RULES (strict):
- Use ONLY the SOURCES below. Cite with the exact SOURCE tag in square brackets, e.g. [src: scale-microct/src/segment.py:1-80].
- Never invent numbers, results, file names, citations, people, or work. A number appears only if a source states it, with its citation.
- In chat logs, lines marked "${me.toUpperCase()} (user)" are ${me}'s own words; "AI" lines are an assistant's suggestions. They're not proof that something was built or worked.
- Keep what ${me} personally built separate from what already existed or was built by the lab, collaborators, the scanner vendor (SCANCO), or libraries. If ownership is unclear, say "unclear from my sources".`

export async function makeBrief(gem: Gemini, cfg: CueConfig, digest: string, manifest: Manifest, log: (s: string) => void): Promise<{ text: string; model: string }> {
  const me = cfg.meeting.me
  const system = `You prepare ${me}, a high-school researcher, for a meeting with ${cfg.meeting.with} about "${cfg.meeting.topic}".
${GROUNDING(me)}`
  const prompt = `Write brief.md: ONE page (about 700 words max) in plain first-person language ("I built…"), Markdown, these sections:
1. **What the project is** (2–3 sentences)
2. **What I built vs. what already existed / others built** (two short lists)
3. **Pipeline stages**: each stage with inputs → outputs (a compact list)
4. **Key design decisions and why**: mine these from the chat logs, with dates when available
5. **Real numbers**: resolution, voxel size, dataset sizes, runtimes. ONLY if a source states them, each with a citation. If none are found, say so.
6. **What works / what doesn't yet**
7. **Open problems**
8. **Next steps toward Abaqus FEM**
9. **Glossary** (terms a professor might use: one line each)
Cite sources inline. If a section can't be grounded, write "Not in my sources" rather than guessing.

${manifestSummary(manifest)}

SOURCES:
${digest}`
  const r = await streamBrain(gem, {
    system,
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    thinking: cfg.gemini.thinking.prep,
    chain: gem.brainChain,
    signal: new AbortController().signal,
    maxWaitMs: 70_000,
    retrySameMs: 90_000,
    onSkip: skipLog,
    onText: (t) => log(`  brief: ${t.length} chars`)
  })
  return { text: r.text.trim(), model: r.model }
}

const QA_SCHEMA = {
  type: 'array',
  items: {
    type: 'object',
    properties: {
      question: { type: 'string', description: 'What the professor would literally ask' },
      category: { type: 'string', enum: ['technical', 'why-not', 'limitations', 'validation', 'failure-cases', 'next-steps', 'more-time', 'background'] },
      lead: { type: 'string', description: 'One-line first-person answer to say first' },
      bullets: { type: 'array', items: { type: 'string' }, description: '2-3 concrete talking points' },
      deeper: { type: 'string', description: 'One deeper point if pushed' },
      sources: { type: 'array', items: { type: 'string' }, description: 'Exact SOURCE tags that support the answer' },
      verified: { type: 'boolean', description: 'false if the answer is not grounded in the sources' }
    },
    required: ['question', 'category', 'lead', 'bullets', 'deeper', 'sources', 'verified']
  }
}

export async function makeQaBank(gem: Gemini, cfg: CueConfig, digest: string, brief: string, count = 40): Promise<{ entries: QaEntry[]; model: string }> {
  const me = cfg.meeting.me
  const system = `You prepare ${me}, a high-school researcher, for questions from ${cfg.meeting.with} about "${cfg.meeting.topic}".
${GROUNDING(me)}`
  const prompt = `Generate about ${count} questions a professor would likely ask in this meeting: technical deep-dives, "why not X?", limitations, validation, failure cases, next steps, "what would you do with more time?", background.
For each: a one-line first-person lead, 2–3 bullets with concrete specifics (numbers, file/function names, methods) ONLY from the sources, one deeper point, and the exact SOURCE tags used.
If the sources can't answer a question, still include it (they're the most important to prepare): set verified=false, make the lead start with "Not in my notes:", and give an honest bridge ("I haven't tested that yet; my guess is X because Y; I'll follow up"). Use sources [] in that case.

BRIEF (already grounded, for orientation):
${brief}

SOURCES:
${digest}`
  const r = await generateJson<QaEntry[]>(gem, {
    system,
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    schema: QA_SCHEMA,
    thinking: cfg.gemini.thinking.prep,
    chain: gem.brainChain,
    maxWaitMs: 70_000,
    retrySameMs: 90_000,
    onSkip: skipLog
  })
  return { entries: Array.isArray(r.value) ? r.value : [], model: r.model }
}

/** Drops citations that don't match any chunk; an answer left with none becomes unverified. */
export function checkCitations(entries: QaEntry[], chunks: Chunk[]): { entries: QaEntry[]; dropped: number } {
  const tags = chunks.map((c) => c.source.toLowerCase())
  const known = (s: string) => {
    const t = cleanSource(s).toLowerCase()
    if (!t || t === 'brief.md') return false
    return tags.some((tag) => tag === t || tag.startsWith(t) || t.startsWith(tag.split(':')[0]))
  }
  let dropped = 0
  const out = entries.map((e) => {
    const sources = [...new Set((e.sources ?? []).map(cleanSource))].filter((s) => {
      const ok = known(s)
      if (!ok) dropped++
      return ok
    })
    return {
      ...e,
      bullets: (e.bullets ?? []).slice(0, 4),
      sources,
      verified: Boolean(e.verified) && sources.length > 0
    }
  })
  return { entries: out, dropped }
}

export function renderQaMarkdown(entries: QaEntry[], cfg: CueConfig): string {
  const groups = new Map<string, QaEntry[]>()
  for (const e of entries) groups.set(e.category || 'other', [...(groups.get(e.category || 'other') ?? []), e])
  const unverified = entries.filter((e) => !e.verified).length
  const lines = [
    `# Q&A bank: ${cfg.meeting.topic}`,
    '',
    `${entries.length} likely questions from ${cfg.meeting.with}. ${unverified} marked ⚠️ UNVERIFIED (not grounded in your sources; see gaps.md).`,
    ''
  ]
  let n = 0
  for (const [cat, list] of groups) {
    lines.push(`## ${cat}`, '')
    for (const e of list) {
      lines.push(`### ${++n}. ${e.question}${e.verified ? '' : ' ⚠️ UNVERIFIED'}`, '', `**${e.lead}**`)
      for (const b of e.bullets) lines.push(`- ${b}`)
      if (e.deeper) lines.push(`- ↳ If pushed: ${e.deeper}`)
      lines.push(`- _sources: ${e.sources.length ? e.sources.join(', ') : 'none'}_`, '')
    }
  }
  return lines.join('\n')
}

export async function makeGaps(gem: Gemini, cfg: CueConfig, digest: string, brief: string, qa: QaEntry[], manifest: Manifest): Promise<{ text: string; model: string }> {
  const me = cfg.meeting.me
  const unverified = qa.filter((e) => !e.verified).map((e) => `- ${e.question}`)
  const system = `You are a demanding but kind research mentor preparing ${me} for a meeting with ${cfg.meeting.with} about "${cfg.meeting.topic}".
${GROUNDING(me)}`
  const prompt = `Write gaps.md: things ${me} should know cold that the sources DON'T answer (or answer only vaguely), so ${me} can fix them before the meeting.
Group under headings: Numbers I should know · Validation & accuracy · Design choices I can't yet justify · Scanner & compression setup (SCANCO microCT100HE, TD-309) · Path to Abaqus FEM · Ownership (what I did vs. others) · Other.
For each gap: one line on what's missing, one line on why the professor will care, and where ${me} could find it (a file to check, a measurement to run, a person to ask). Skip anything the sources already answer well. Be specific to this project, not generic.

Questions the Q&A bank couldn't ground:
${unverified.join('\n') || '- (none)'}

${manifestSummary(manifest)}

BRIEF:
${brief}

SOURCES:
${digest}`
  const r = await streamBrain(gem, {
    system,
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    thinking: cfg.gemini.thinking.prep,
    chain: gem.brainChain,
    signal: new AbortController().signal,
    maxWaitMs: 70_000,
    retrySameMs: 90_000,
    onSkip: skipLog
  })
  return { text: r.text.trim(), model: r.model }
}

const SLIDE_SCHEMA = {
  type: 'array',
  items: {
    type: 'object',
    properties: {
      index: { type: 'integer' },
      talking_points: { type: 'array', items: { type: 'string' }, description: 'Exactly 3, first person, at most 14 words each' },
      likely_question: { type: 'string' },
      answer: { type: 'string', description: 'One-line first-person answer, at most 30 words, grounded' },
      sources: { type: 'array', items: { type: 'string' } }
    },
    required: ['index', 'talking_points', 'likely_question', 'answer', 'sources']
  }
}

export async function makeSlidePrep(gem: Gemini, cfg: CueConfig, slides: SlideInfo[], brief: string, qa: QaEntry[], digest: string): Promise<{ items: SlidePrep[]; model: string }> {
  const me = cfg.meeting.me
  const deck = slides.map((s) => `SLIDE ${s.index}: ${s.title}\n${s.text}${s.notes ? `\nNotes: ${s.notes}` : ''}`).join('\n\n')
  const bank = qa.map((e) => `- ${e.question} → ${e.lead}${e.verified ? '' : ' (unverified)'}`).join('\n')
  const system = `You prepare ${me} to present slides to ${cfg.meeting.with}.
${GROUNDING(me)}`
  const prompt = `For EVERY slide below, give: 3 talking points ${me} can say naturally (first person, ≤14 words each, from the slide + sources), the single most likely question the professor asks on that slide, and a one-line grounded answer (reuse the Q&A bank where it fits). Cite SOURCE tags. If the answer isn't in the sources, start it with "Not in my notes:" and give an honest bridge.

DECK:
${deck}

Q&A BANK:
${bank}

BRIEF:
${brief}

SOURCES:
${digest}`
  const r = await generateJson<SlidePrep[]>(gem, {
    system,
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    schema: SLIDE_SCHEMA,
    thinking: cfg.gemini.thinking.prep,
    chain: gem.brainChain,
    maxWaitMs: 70_000,
    retrySameMs: 90_000,
    onSkip: skipLog
  })
  return { items: Array.isArray(r.value) ? r.value : [], model: r.model }
}

export { estimateTokens }
